g=[[0,5,0,0,0,0,0,5,0,0,5,0],[0,5,0,0,0,5,5,5,0,5,5,0],[5,5,5,0,0,5,0,5,5,5,0,0],[0,0,5,5,5,5,0,5,0,5,5,0],[0,0,0,5,0,0,0,5,0,0,5,0]]
# components 4-connected zeros
H,W=len(g),len(g[0]); seen=set(); comps=[]
for r in range(H):
 for c in range(W):
  if g[r][c]==0 and (r,c) not in seen:
   st=[(r,c)];seen.add((r,c)); comp=[]
   while st:
    x,y=st.pop();comp.append((x,y))
    for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
     if 0<=a<H and 0<=b<W and g[a][b]==0 and (a,b) not in seen: seen.add((a,b));st.append((a,b))
   comps.append(comp)
[(len(x), (min(r for r,c in x),max(r for r,c in x),min(c for r,c in x),max(c for r,c in x)), any(r in (0,H-1) or c in (0,W-1) for r,c in x)) for x in comps]
